}

functions.confirm:
{
   if(this.roleUse.nowState == true)
   {
      battlePanel = _parent.rolePanel;
   }
   else if(this.battleHuanShou(this.mainHuanShou) == false)
   {
      _global.sysMsg.addMsg("请先把幻兽出征。");
      return false;
   }
   if(this._parent.backPack.accountThing({type:"经验球"}) >= 1)
   {
      if(this.battlePanel.setThing({type:"经验球"}) == true)
      {
         this._parent.backPack.useThing({type:"经验球"},1);
      }
      return true;
   }
   _global.sysMsg.addMsg("你的物品栏里没有足够的经验球");
   return false;
}

