functions.setThing:
{
   if(target.type == "经验球" && this.useExpball(2000))
   {
      if(target.number > 1)
      {
         target.number -= 1;
         return false;
      }
      return true;
   }
   if(target.type == "转世圣水")
   {
      if(this.role.life == 0)
      {
         _global.sysMsg.addMsg("死亡状态，不能使用此物品！");
         return false;
      }
      return role.upGod();
   }
   if(target.type == "超级经验球")
   {
      if(this.role.expBallNum < this.role.levels)
      {
         this.role.expBallNum++;
         this.role.moreExpFire += 2;
         this.role.moreExpLife += 2;
         this.role.moreExpMp += 2;
         this.role.moreExpAttack += 2;
         this.role.moreExpDefense += 2;
         this.role.flashAttribute();
         _global.sysMsg.addMsg("使用超级经验球，人物战斗力+2、攻击力+2％、防御力+2％、生命值+2％、魔力值+2％");
         _global.sysMsg.addMsg("第" + this.role.expBallNum + "次使用超级经验球。人物" + this.role.levels + "级最多可以使用" + this.role.levels + "次超级经验球。");
      }
      else
      {
         _global.sysMsg.addMsg("人物当前等级：" + this.role.levels + "，你已经使用过" + this.role.expBallNum + "次超级经验球了，不能再使用。");
      }
      if(target.number > 1)
      {
         target.number -= 1;
         return false;
      }
      return true;
   }
   if(target.type == "能量药水")
   {
      if(_root.XPPower.maxPower < _root.XPPower.maxTopPower)
      {
         _root.XPPower.maxPower += 1;
         _root.XPPower.isFull = false;
         _global.sysMsg.addMsg("XP能量格上限增加至" + _root.XPPower.maxPower);
         if(target.number > 1)
         {
            target.number -= 1;
            return false;
         }
         return true;
      }
      _global.sysMsg.addMsg("XP能量格上限已经达到" + _root.XPPower.maxTopPower + "，不能继续使用些药品了");
      return false;
   }
   if(target.type == "药品" && this.role.life > 0)
   {
      if(!isNaN(target.hpVal))
      {
         this.role.life += target.hpVal;
      }
      if(!isNaN(target.mpVal))
      {
         this.role.mp += target.mpVal;
      }
      return true;
   }
   var _loc6_;
   if(target.type == "生命之源" && this.role.life > 0)
   {
      _loc6_ = this.role.maxLife - this.role.life;
      if(this.role.lifeSourse >= _loc6_)
      {
